class Solution:
    def splitArraySameAverage(self, nums):
        n, S = len(nums), sum(nums)
        if all(x * n == S for x in nums):
            return True
        half = n // 2
        left, right = nums[:half], nums[half:]

        def subsets(arr):
            m = len(arr)
            res = [dict() for _ in range(m + 1)]
            for mask in range(1 << m):
                sz = s = 0
                for i in range(m):
                    if mask >> i & 1:
                        sz += 1
                        s += arr[i]
                res[sz].setdefault(s, True)
            return res

        L, R = subsets(left), subsets(right)
        for a in range(half + 1):
            for sa in L[a]:
                for b in range(len(right) + 1):
                    if a + b == 0 or a + b >= n:
                        continue
                    num = (a + b) * S - n * sa
                    if num % n:
                        continue
                    sb = num // n
                    if sb in R[b]:
                        return True
        return False

