class Solution {
public:
    bool splitArraySameAverage(vector<int>& nums) {
        int n = nums.size();
        long long S = accumulate(nums.begin(), nums.end(), 0LL);
        bool allEq = true;
        for (int x : nums) if ((long long)x * n != S) allEq = false;
        if (allEq) return true;
        int h = n / 2;
        vector<int> L(nums.begin(), nums.begin() + h), R(nums.begin() + h, nums.end());
        auto build = [](vector<int>& v) {
            int m = v.size();
            vector<unordered_set<long long>> res(m + 1);
            for (int mask = 0; mask < (1 << m); mask++) {
                long long s = 0; int sz = 0;
                for (int i = 0; i < m; i++) if (mask >> i & 1) { sz++; s += v[i]; }
                res[sz].insert(s);
            }
            return res;
        };
        auto lm = build(L), rm = build(R);
        for (int a = 0; a <= h; a++)
            for (long long sa : lm[a])
                for (int b = 0; b <= (int)R.size(); b++) {
                    if (a + b == 0 || a + b >= n) continue;
                    long long num = (long long)(a + b) * S - (long long)n * sa;
                    if (num % n) continue;
                    if (rm[b].count(num / n)) return true;
                }
        return false;
    }
};

