class Solution {
    public boolean splitArraySameAverage(int[] nums) {
        int n = nums.length;
        long S = 0;
        for (int x : nums) S += x;
        boolean allEq = true;
        for (int x : nums) if ((long) x * n != S) allEq = false;
        if (allEq) return true;
        int h = n / 2;
        int[] L = Arrays.copyOfRange(nums, 0, h), R = Arrays.copyOfRange(nums, h, n);
        List<Set<Long>> lm = build(L), rm = build(R);
        for (int a = 0; a <= h; a++)
            for (long sa : lm.get(a))
                for (int b = 0; b <= R.length; b++) {
                    if (a + b == 0 || a + b >= n) continue;
                    long num = (long)(a + b) * S - (long) n * sa;
                    if (num % n != 0) continue;
                    if (rm.get(b).contains(num / n)) return true;
                }
        return false;
    }
    private List<Set<Long>> build(int[] v) {
        int m = v.length;
        List<Set<Long>> res = new ArrayList<>();
        for (int i = 0; i <= m; i++) res.add(new HashSet<>());
        for (int mask = 0; mask < (1 << m); mask++) {
            long s = 0; int sz = 0;
            for (int i = 0; i < m; i++) if ((mask >> i & 1) == 1) { sz++; s += v[i]; }
            res.get(sz).add(s);
        }
        return res;
    }
}

