class Solution {
    public boolean splitArraySameAverage(int[] nums) {
        int n = nums.length, S = 0;
        for (int x : nums) S += x;
        boolean any = false;
        for (int k = 1; k <= n / 2; k++) if ((long) k * S % n == 0) any = true;
        if (!any) return false;
        final int MAXS = 300001;
        BitSet[] dp = new BitSet[n + 1];
        for (int i = 0; i <= n; i++) dp[i] = new BitSet(MAXS);
        dp[0].set(0);
        for (int x : nums)
            for (int k = n - 1; k >= 0; k--) {
                BitSet shifted = new BitSet(MAXS);
                for (int b = dp[k].nextSetBit(0); b >= 0 && b + x < MAXS; b = dp[k].nextSetBit(b + 1))
                    shifted.set(b + x);
                dp[k + 1].or(shifted);
            }
        for (int k = 1; k <= n / 2; k++)
            if ((long) k * S % n == 0 && dp[k].get((int)((long) k * S / n)))
                return true;
        return false;
    }
}

