var splitArraySameAverage = function(nums) {
    const n = nums.length, S = nums.reduce((a, b) => a + b, 0);
    const ks = [];
    for (let k = 1; k <= Math.floor(n / 2); k++)
        if ((k * S) % n === 0) ks.push(k);
    if (!ks.length) return false;
    let dp = Array.from({length: n + 1}, () => new Set());
    dp[0].add(0);
    for (const x of nums)
        for (let k = n - 1; k >= 0; k--)
            for (const s of dp[k]) dp[k + 1].add(s + x);
    for (const k of ks)
        if (dp[k].has(k * S / n)) return true;
    return false;
};
